referenceSolutions.javascript:
export function solve(values) {
  const sum = values.reduce((a, b) => a + b, 0);
  let a = Math.abs(sum),
    b = values.length;
  while (b) {
    const r = a % b;
    a = b;
    b = r;
  }
  return { numerator: sum / a, denominator: values.length / a };
}

